import{_ as r,a0 as s,w as p,s as i,ao as d,I as a,x as t,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"ls命令的20个实用范例 | LCTT x X-CMD","titleTemplate":false,"description":"ls命令的20个实用范例 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ls命令的20个实用范例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ls命令的20个实用范例 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/20 Linux ls Command Examples to Display the Entries of Directory","title":"ls命令的20个实用范例","tag":"201402","desc":""},"relativePath":"201402/20 Linux ls Command Examples to Display the Entries of Directory.md","filePath":"[post].md"}'),c={name:"201402/20 Linux ls Command Examples to Display the Entries of Directory.md"};function h(g,e,m,x,_,u){const o=s("Link");return p(),i("div",null,[e[11]||(e[11]=d(`<h1 id="ls命令的20个实用范例" tabindex="-1">ls命令的20个实用范例 <a class="header-anchor" href="#ls命令的20个实用范例" aria-label="Permalink to “ls命令的20个实用范例”">​</a></h1><p>Linux中一个基本命令是ls。没有这个命令，我们会在浏览目录条目时会遇到困难。这个命令必须被每个学习Linux的人知道。</p><h3 id="ls是什么" tabindex="-1">ls是什么 <a class="header-anchor" href="#ls是什么" aria-label="Permalink to “ls是什么”">​</a></h3><p>ls命令用于列出文件和目录。默认上，他会列出当前目录的内容。带上参数后，我们可以用ls做更多的事情。这里是一些在日常操作中使用到的ls用法的示例。</p><h4 id="_1-不带参数运行ls" tabindex="-1">1. 不带参数运行ls <a class="header-anchor" href="#_1-不带参数运行ls" aria-label="Permalink to “1. 不带参数运行ls”">​</a></h4><p>不带参数运行ls会只列出文件或者目录。看不到其他信息输出（译注：有时候你发现无参数的ls命令和这里描述的不同，那有可能是你的ls命令实际上带参数的ls别名）。</p><pre><code>$ ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls.png" alt=""></p><h4 id="_2-使用长清单模式" tabindex="-1">2. 使用长清单模式 <a class="header-anchor" href="#_2-使用长清单模式" aria-label="Permalink to “2. 使用长清单模式”">​</a></h4><p>使用-l字符(小写L字符),会显示当前目录内容的长列表。在接下来的例子中，我们会结合-l参数(这个参数经常使用)来得到更好的结果。</p><pre><code>$ ls -l
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_l.png" alt=""></p><p>这里是如何读取输出 :</p><ul><li><p><strong>第1列</strong></p><ul><li><p>第一个字母<strong>d</strong>意味着内容是目录或者文件。在上面的截图中，Desktop、 Documents、 Downloads 和 lynis-1.3.8是目录。如果是&#39;-&#39;(<strong>减号</strong>)，这意味着它的内容是文件。当它是l(<strong>小写l字符</strong>)，意味这内容是链接文件。</p></li><li><p>下面的9个字符是关于文件权限。<strong>前3个rwx</strong>字符是文件的拥有者的权限，<strong>第二组3rwx</strong>是文件的所有组的权限，<strong>最后的rwx</strong>是对其他人访问文件的权限。</p></li></ul></li><li><p><strong>第2列</strong> 这行告诉我们有多少链接指向这个文件。</p></li><li><p><strong>第3列</strong> 这行告诉我们谁是这个文件/文件夹的所有者。</p></li><li><p><strong>第4列</strong> 这行告诉我们谁是这个文件/文件夹的所有组。</p></li><li><p><strong>第5列</strong> 这行告诉我们这个文件/文件夹的以字节为单位的大小。 目录的大小总是4096字节。</p></li><li><p><strong>第6列</strong> 这告诉我们文件最后的修改时间。</p></li><li><p><strong>第7列</strong> 这告诉我们文件名或者目录名。</p></li></ul><h4 id="_3-显示文件大小" tabindex="-1">3. 显示文件大小 <a class="header-anchor" href="#_3-显示文件大小" aria-label="Permalink to “3. 显示文件大小”">​</a></h4><p>以字节为单位看大小可能会不方便。6.5M读起来比6727680字节更简单。要这么做，我们可以使用-h与<strong>-l</strong>结合的参数。<strong>-h参数意味着便于人识别</strong>。</p><pre><code>$ ls -lh
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lh1.png" alt=""></p><p>另外一个可以这么做的参数是<strong>--si</strong>。这个参数和-h参数类似，但是<strong>-si以1000为单位，而-h以1024为单位</strong>。</p><pre><code>$ ls -si
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_si.png" alt=""></p><h4 id="_4-排序文件大小" tabindex="-1">4. 排序文件大小 <a class="header-anchor" href="#_4-排序文件大小" aria-label="Permalink to “4. 排序文件大小”">​</a></h4><p>在我们可以显示文件大小之后，我们希望以文件大小排序。我们可以使用-S参数来这么做。这列表会从大到校排序。</p><pre><code>$ ls -lhS
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lhS.png" alt=""></p><h4 id="_5-测量大小" tabindex="-1">5. 测量大小 <a class="header-anchor" href="#_5-测量大小" aria-label="Permalink to “5. 测量大小”">​</a></h4><p>ls可以通过使用<strong>-block-size=SIZE</strong>改单位大小。这里的SIZE是：</p><pre><code>K = Kilobyte
M = Megabyte
G = Gigabyte
T = Terabyte
P = Petabyte
E = Exabyte
Z = Zettabyte
Y = Yottabyte
</code></pre><p>比如，我们希望使用MB作为单位大小。所以语法就会像这样:</p><pre><code>$ ls -l --block-size=M
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_block_size.png" alt=""></p><h4 id="_6-显示隐藏文件" tabindex="-1">6. 显示隐藏文件 <a class="header-anchor" href="#_6-显示隐藏文件" aria-label="Permalink to “6. 显示隐藏文件”">​</a></h4><p>在Linux中，以&quot;.&quot;(<strong>点号</strong>)开头的文件是隐藏文件。为了在ls命令中显示它，我们可以使用<strong>-a</strong>选项。</p><pre><code>$ ls -a
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_a.png" alt=""></p><h4 id="_7-只列出目录条目" tabindex="-1">7. 只列出目录条目 <a class="header-anchor" href="#_7-只列出目录条目" aria-label="Permalink to “7. 只列出目录条目”">​</a></h4><p>如果我们希望只列出目录，我们可以使用<strong>-d</strong>选项。</p><pre><code>$ ls -d */
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_d.png" alt=""></p><h4 id="_8-不打印所有者信息" tabindex="-1">8. 不打印所有者信息 <a class="header-anchor" href="#_8-不打印所有者信息" aria-label="Permalink to “8. 不打印所有者信息”">​</a></h4><p>要这么做，我们使用<strong>-g</strong>选项。</p><pre><code>$ ls -g
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lg.png" alt=""></p><h4 id="_9-不打印组信息" tabindex="-1">9. 不打印组信息 <a class="header-anchor" href="#_9-不打印组信息" aria-label="Permalink to “9. 不打印组信息”">​</a></h4><p>-g隐藏了拥有者信息，<strong>—G</strong>会隐藏组信息。</p><pre><code>$ ls -lG
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lG2.png" alt=""></p><h4 id="_10-打印uid和gid" tabindex="-1">10. 打印UID和GID <a class="header-anchor" href="#_10-打印uid和gid" aria-label="Permalink to “10. 打印UID和GID”">​</a></h4><p>如果你想以数字方式列出项的所有者和所有组（即UID和GID），我们可以带<strong>-n</strong>选项使用ls命令。这里是个例子。</p><pre><code>$ ls -n
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_n.png" alt=""></p><p>从上面的例子中，我们知道<strong>用户pungki的UID</strong>是100，<strong>GID是1000</strong>，而<strong>root组的GID是0</strong>。</p><h4 id="_11-不带颜色打印" tabindex="-1">11. 不带颜色打印 <a class="header-anchor" href="#_11-不带颜色打印" aria-label="Permalink to “11. 不带颜色打印”">​</a></h4><p>一些Linux发行版已经对ls命令启用彩色。这会使ls以各种颜色打印列表。如果你不想要这样，你可以使用 <strong>--color=never</strong> 参数。</p><pre><code>$ ls --color=never
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_color_never.png" alt=""></p><h4 id="_12-打印每个文件的索引号" tabindex="-1">12. 打印每个文件的索引号 <a class="header-anchor" href="#_12-打印每个文件的索引号" aria-label="Permalink to “12. 打印每个文件的索引号”">​</a></h4><p>为了打印索引或者大家俗称的inode号，我们可以使用-i选项。索引号会显示在第一列。</p><pre><code>$ ls -li
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_inode.png" alt=""></p><h4 id="_13-增加-斜线-标记目录" tabindex="-1">13. 增加 / (斜线) 标记目录 <a class="header-anchor" href="#_13-增加-斜线-标记目录" aria-label="Permalink to “13. 增加 / (斜线) 标记目录”">​</a></h4><p>要这么做，使用<strong>-p选项</strong>。</p><pre><code>$ ls -p
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_p.png" alt=""></p><h4 id="_14-排序时反转顺序" tabindex="-1">14. 排序时反转顺序 <a class="header-anchor" href="#_14-排序时反转顺序" aria-label="Permalink to “14. 排序时反转顺序”">​</a></h4><p>你或许需要在列出条目时反转顺序。要这么做，你可以使用<strong>-r</strong>选项。</p><pre><code>$ ls -r
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_r.png" alt=""></p><h4 id="_15-递归列出子目录" tabindex="-1">15. 递归列出子目录 <a class="header-anchor" href="#_15-递归列出子目录" aria-label="Permalink to “15. 递归列出子目录”">​</a></h4><p>带<strong>-R</strong>参数后，你可以列出包含它子目录的目录。</p><pre><code>$ ls -R
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_Recursive.png" alt=""></p><h4 id="_16-扩展名排序" tabindex="-1">16. 扩展名排序 <a class="header-anchor" href="#_16-扩展名排序" aria-label="Permalink to “16. 扩展名排序”">​</a></h4><p>你可以使用-X参数或者--sort=extension来通过扩展名来排序（译注：这样对于筛选不同类型的文件很有用）。</p><pre><code>$ ls -lX
</code></pre><p><strong>或</strong></p><pre><code>$ ls --sort=extension
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_x.png" alt=""></p><h4 id="_17-通过修改时间列出" tabindex="-1">17. 通过修改时间列出 <a class="header-anchor" href="#_17-通过修改时间列出" aria-label="Permalink to “17. 通过修改时间列出”">​</a></h4><p>使用-t选项会按修改时间排序，新的文件在前。</p><pre><code>$ ls -lt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_lt.png" alt=""></p><h4 id="_18-列出你的主目录" tabindex="-1">18. 列出你的主目录 <a class="header-anchor" href="#_18-列出你的主目录" aria-label="Permalink to “18. 列出你的主目录”">​</a></h4><p>要列出你的主目录，你可以用&quot;~&quot;(<strong>波浪号</strong>)来代表它。这样你就不必输入完整的目录名。让我们假设家文件名为<strong>/home/pungki</strong>，那么<strong>波浪号</strong>就对/home/pungki有意义了。</p><pre><code>$ ls ~
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_tilde.png" alt=""></p><h4 id="_19-列出父目录" tabindex="-1">19. 列出父目录 <a class="header-anchor" href="#_19-列出父目录" aria-label="Permalink to “19. 列出父目录”">​</a></h4><p>无论你在那个目录，你可以列出父目录而不必输入完整路径。这是个例子。</p><pre><code>$ ls ../
</code></pre><p>这回列出<strong>1</strong>层之上的目录内容。</p><pre><code>$ ls ../../
</code></pre><p>这回列出<strong>2</strong>层之上的目录内容（译注：可不支持“...”来代表2层之上）。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_parent.png" alt=""></p><h4 id="_20-打印ls命令版本" tabindex="-1">20. 打印ls命令版本 <a class="header-anchor" href="#_20-打印ls命令版本" aria-label="Permalink to “20. 打印ls命令版本”">​</a></h4><p>使用--version参数打印它。</p><pre><code>$ ls --version
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ls_version.png" alt=""></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>这些是在日常操作中会使用到的参数。当然你总可以输入<strong>man ls</strong> 或者 <strong>ls --help</strong> 来查询ls的手册页</p><hr>`,100)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),n(o,{href:"http://linoxide.com/linux-command/linux-ls-command/"},{default:l(()=>[...e[0]||(e[0]=[t("http://linoxide.com/linux-command/linux-ls-command/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=t("译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:l(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:l(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const P=r(c,[["render",h]]);export{k as __pageData,P as default};
